#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int ket_noi = 0, nhan_du_lieu = 0;
    for (int i = 0; i < n; i++) {
        char su_kien[32];
        if (scanf("%31s", su_kien) != 1) return 1;
        if (strcmp(su_kien, "conn") == 0) ket_noi++;
        else if (strcmp(su_kien, "data") == 0) nhan_du_lieu++;
    }
    printf("%d %d\n", ket_noi, nhan_du_lieu);
    return 0;
}
